import { test, expect } from '@playwright/test';

test.describe('Browser Back Button Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should navigate to previous page using browser Back button without breaking app state', async ({ page }) => {
    // Verify initial page content
    const dashboardTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardTitle).toBeVisible();

    // Navigate to a new page
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    const settingsPageTitle = page.getByRole('heading', { name: /settings/i });
    await expect(settingsPageTitle).toBeVisible();

    // Verify app state is preserved
    const dashboardNav = page.getByRole('navigation', { name: /dashboard/i });
    await expect(dashboardNav).toBeVisible();

    // Verify settings page content
    const settingsContent = page.getByText(/settings/i);
    await expect(settingsContent).toBeVisible();

    // Navigate back using browser Back button
    await page.evaluate(() => window.history.back());

    // Verify we are back to dashboard
    await expect(dashboardPageTitle).toBeVisible();

    // Verify app state is preserved
    await expect(dashboardNav).toBeVisible();

    // Verify dashboard content is still visible
    const dashboardContent = page.getByText(/dashboard/i);
    await expect(dashboardContent).toBeVisible();

    // Verify navigation history is correct
    const historyCount = page.evaluate(() => window.history.length);
    await expect(historyCount).toBeGreaterThan(1);
  });

  test('should handle edge case where no previous page exists', async ({ page }) => {
    // Navigate to a page with no previous page
    const noPreviousPageButton = page.getByRole('button', { name: /no previous page/i });
    await noPreviousPageButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/no previous page/i);
    await expect(errorMessage).toBeVisible();

    // Verify navigation history is empty
    const historyCount = page.evaluate(() => window.history.length);
    await expect(historyCount).toBe(1);

    // Verify app state is not broken
    const dashboardNav = page.getByRole('navigation', { name: /dashboard/i });
    await expect(dashboardNav).toBeVisible();

    // Verify user can navigate to a different page
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    const settingsPageTitle = page.getByRole('heading', { name: /settings/i });
    await expect(settingsPageTitle).toBeVisible();

    // Verify app state is preserved
    await expect(dashboardNav).toBeVisible();
  });
});
